language sql
immutable
set search_path to 'pg_catalog'
as $function$
  select $drill${"key":"ai_calls","fact":"ai_calls","mode":"definer","grain":"one row per model call (chat.request): the model that answered, its provider, tokens, cost, latency and status","label":"AI model calls","lanes":["platform","organization","mine"],"paths":[{"key":"what","label":"What","levels":["provider","model"]},{"key":"who","label":"Who","levels":["organization","person","session"]},{"key":"thread","label":"Conversation","levels":["conversation","request","iteration"]},{"key":"when","label":"When","levels":["at:day","at:hour","bucket_10m"]}],"views":[{"key":"cx_by_model","label":"Usage by model","question":{"by":["model","provider"],"show":["calls","cost","tokens_in","tokens_out","tokens_cached","tokens_total","latency"],"sort":{"key":"calls","direction":"desc"}}},{"key":"cx_by_provider","label":"Cost by provider","question":{"by":["provider"],"show":["calls","cost","tokens_total"],"sort":{"key":"calls","direction":"desc"}}},{"key":"cx_by_day","label":"Daily cost and tokens","question":{"by":["at:day"],"show":["calls","cost","tokens_in","tokens_out","tokens_cached"],"sort":{"key":"at:day","direction":"asc"}}},{"key":"cx_tokens_by_day","chart":{"stack":["tokens_in","tokens_out"]},"label":"Daily input and output tokens","question":{"by":["at:day"],"show":["tokens_in","tokens_out"],"sort":{"key":"at:day","direction":"asc"}}},{"key":"cx_by_origin","label":"Cost by origin","question":{"by":["origin"],"show":["calls","cost","tokens_in","tokens_out","tokens_cached","tokens_total"],"sort":{"key":"cost","direction":"desc"}}},{"key":"cx_cost_share","label":"Cost share by model","question":{"by":["model","provider"],"show":["cost","calls"],"sort":{"key":"cost","direction":"desc"}}},{"key":"cx_latency","label":"Latency by model","question":{"by":["model","provider"],"show":["latency","latency_median","calls"],"sort":{"key":"latency","direction":"desc"}}},{"key":"reconcile_calls","label":"Model-call cost by whether the ledger holds the request (to reconcile with the ledger)","question":{"by":["request_in_ledger"],"show":["cost","calls"],"sort":{"key":"cost","direction":"desc"}}}],"detail":{"open":"/administration/chat/cx-dashboard/usage","columns":["created_at","model","provider","status","iteration","cost","tokens_in","tokens_out","latency_ms"]},"default":{"by":["model"],"path":"what","show":["calls","cost","latency"],"sort":{"key":"cost","direction":"desc"},"window":{"key":"at","preset":"30d"}},"measures":[{"of":"calls","op":"sum","key":"calls","unit":"count","label":"Calls","additive":true,"description":"Every model call, automated runs included; a request that looped is several calls"},{"of":"cost","op":"sum","key":"cost","unit":"usd","label":"Cost","additive":true},{"of":"tokens_in","op":"sum","key":"tokens_in","unit":"tokens","label":"Input tokens","additive":true},{"of":"tokens_out","op":"sum","key":"tokens_out","unit":"tokens","label":"Output tokens","additive":true},{"of":"tokens_cached","op":"sum","key":"tokens_cached","unit":"tokens","label":"Cached tokens","additive":true},{"of":"tokens_total","op":"sum","key":"tokens_total","unit":"tokens","label":"Total tokens","additive":true},{"of":"latency_ms","op":"avg","key":"latency","unit":"ms","label":"Average latency","additive":false},{"of":"latency_ms","op":"median","key":"latency_median","unit":"ms","label":"Median latency","additive":false},{"of":"unpriced_calls","op":"sum","key":"unpriced_calls","unit":"count","label":"Calls with no price","additive":true},{"of":"request_id","op":"count_distinct","key":"requests","unit":"count","label":"Requests","additive":false,"description":"Distinct requests behind these model calls"},{"of":"person_id","op":"count_distinct","key":"people","unit":"count","label":"People","additive":false},{"op":"ratio","den":"calls","key":"cost_per_call","num":["cost"],"unit":"usd","label":"Cost per call"},{"of":"created_at","op":"min","key":"started","unit":"time","label":"Started","additive":false},{"of":"created_at","op":"max","key":"last_activity","unit":"time","label":"Last active","additive":false}],"dimensions":[{"key":"organization","from":"organization_id","kind":"relation","label":"Organization","relation":{"token":"organization"}},{"key":"person","from":"person_id","kind":"relation","label":"Person","level":{"breakouts":["provider","model","agent","conversation","at:day"],"attributes":["organization"]},"relation":{"token":"user","person":true}},{"key":"agent","from":"agent_id","kind":"relation","label":"Agent","level":{"breakouts":["person","model","provider","conversation","at:day"]},"relation":{"token":"agent"},"cardinality":"medium"},{"key":"model","from":"model","kind":"text","label":"Model","level":{"attributes":["provider"]},"cardinality":"medium"},{"key":"provider","from":"provider","kind":"choice","label":"Provider","cardinality":"low"},{"key":"origin","from":"origin","kind":"choice","label":"Origin","choices":[{"color":"--matrx-chart-1","label":"Human","value":"human"},{"color":"--matrx-chart-9","label":"Client auto","value":"client_auto"},{"color":"--matrx-chart-7","label":"API caller","value":"api"},{"color":"--matrx-chart-3","label":"Child agent","value":"child_agent"},{"color":"--matrx-chart-4","label":"Workflow","value":"workflow"},{"color":"--matrx-chart-5","label":"Scheduled","value":"scheduled"},{"color":"--matrx-chart-6","label":"System","value":"system"},{"color":"--matrx-chart-other","label":"Unknown","value":"unknown"}],"cardinality":"low","empty_label":"Unknown"},{"key":"status","from":"status","kind":"choice","label":"Status","cardinality":"low"},{"key":"finish_reason","from":"finish_reason","kind":"choice","label":"Finish reason","cardinality":"low"},{"key":"iteration","from":"iteration","kind":"choice","label":"Iteration","cardinality":"medium"},{"key":"request","from":"request_id","kind":"relation","label":"Request","relation":{"token":"cx_user_request"},"cardinality":"high"},{"key":"conversation","from":"conversation_id","kind":"relation","label":"Conversation","level"